const validTools=['pdf','image','qr','social','palette','units'];function openTool(id,push=true){if(!validTools.includes(id))id='pdf';$$('[data-panel]').forEach(p=>p.classList.toggle('active',p.dataset.panel===id));$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===id));if(push){history.replaceState(null,'',`?tool=${id}`);scrollTo({top:$('.tool-tabs').offsetTop-90,behavior:'smooth'})}if(id==='pdf')ensurePdf();if(id==='qr')ensureQr()}$$('[data-tool]').forEach(b=>b.onclick=()=>openTool(b.dataset.tool));

// PDF — all processing remains in this browser.
let pdfReady=false,pdfDocs=[],pdfOrder=[];async function ensurePdf(){if(pdfReady)return;const msg=$('#pdfMessage');try{await Promise.all([loadScript('https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js','PDFLib'),loadScript('https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.min.js','pdfjsLib')]);pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js';pdfReady=true}catch(e){msg.textContent=e.message}}
function parsePages(text,max){const set=new Set();text.split(',').forEach(x=>{const [a,b]=x.trim().split('-').map(Number);if(!a)return;for(let i=a;i<=(b||a);i++)if(i>=1&&i<=max)set.add(i-1)});return [...set]}
async function loadPdfFiles(){await ensurePdf();pdfDocs=[];pdfOrder=[];const files=[...$('#pdfFiles').files],preview=$('#pdfPagesPreview');preview.textContent='';$('#pdfFileStatus').textContent=`${files.length} file(s)`;for(const file of files){if(file.type==='application/pdf'){const bytes=await file.arrayBuffer();pdfDocs.push({file,bytes});if(pdfDocs.length===1){const view=await pdfjsLib.getDocument({data:bytes.slice(0)}).promise;for(let i=1;i<=view.numPages;i++){pdfOrder.push(i-1);const card=document.createElement('div');card.className='page-card';card.draggable=true;card.dataset.page=i-1;const c=document.createElement('canvas'),p=await view.getPage(i),vp=p.getViewport({scale:.28});c.width=vp.width;c.height=vp.height;await p.render({canvasContext:c.getContext('2d'),viewport:vp}).promise;const label=document.createElement('span');label.textContent=`Page ${i}`;card.append(c,label);card.onclick=()=>card.classList.toggle('selected');card.ondragstart=e=>e.dataTransfer.setData('text/plain',card.dataset.page);card.ondragover=e=>e.preventDefault();card.ondrop=e=>{e.preventDefault();const from=Number(e.dataTransfer.getData('text/plain')),to=Number(card.dataset.page),fi=pdfOrder.indexOf(from),ti=pdfOrder.indexOf(to);pdfOrder.splice(ti,0,pdfOrder.splice(fi,1)[0]);pdfOrder.forEach(n=>preview.append(preview.querySelector(`[data-page="${n}"]`)))};preview.append(card)}}}}}
$('#pdfFiles').onchange=loadPdfFiles;
$('#pdfProcess').onclick=async()=>{const msg=$('#pdfMessage');msg.textContent='Working…';try{await ensurePdf();const {PDFDocument,StandardFonts,rgb,degrees}=PDFLib,action=$('#pdfAction').value,files=[...$('#pdfFiles').files];let out=await PDFDocument.create();if(action==='text'){const font=await out.embedFont(StandardFonts.Helvetica),page=out.addPage([595,842]),lines=$('#pdfText').value.match(/.{1,80}/g)||[''];lines.forEach((t,i)=>page.drawText(t,{x:42,y:790-i*20,size:12,font,color:rgb(.1,.1,.1)}))}else if(action==='images'){for(const f of files){if(!f.type.startsWith('image/'))continue;const bytes=await f.arrayBuffer(),img=f.type==='image/png'?await out.embedPng(bytes):await out.embedJpg(bytes),p=out.addPage([img.width,img.height]);p.drawImage(img,{x:0,y:0,width:img.width,height:img.height})}}else if(action==='merge'){for(const d of pdfDocs){const src=await PDFDocument.load(d.bytes),pages=await out.copyPages(src,src.getPageIndices());pages.forEach(p=>out.addPage(p))}}else{if(!pdfDocs[0])throw new Error('Choose a PDF first');const src=await PDFDocument.load(pdfDocs[0].bytes),all=pdfOrder.length?pdfOrder:src.getPageIndices(),chosen=parsePages($('#pdfPages').value,src.getPageCount());let ids=all;if(action==='extract'||action==='split')ids=chosen.length?chosen:all;if(action==='delete')ids=all.filter(i=>!chosen.includes(i));const pages=await out.copyPages(src,ids);pages.forEach((p,j)=>{if(action==='rotate'&&(!chosen.length||chosen.includes(ids[j])))p.setRotation(degrees((p.getRotation().angle+90)%360));out.addPage(p)})}const bytes=await out.save({useObjectStreams:true});download(new Blob([bytes],{type:'application/pdf'}),action==='split'?'selected-pages.pdf':'fourth-dimension.pdf');msg.textContent=`Ready — ${(bytes.length/1024).toFixed(0)} KB`}catch(e){msg.textContent=e.message}};

// Image toolkit.
let imageSource=null,imageOriginalSize=0;function readImage(file,done){if(!file)return;const img=new Image();img.onload=()=>done(img);img.src=URL.createObjectURL(file)}$('#imageFile').onchange=()=>{const f=$('#imageFile').files[0];imageOriginalSize=f?.size||0;readImage(f,img=>{imageSource=img;$('#imgW').value=img.width;$('#imgH').value=img.height;$('#cropW').value=img.width;$('#cropH').value=img.height;$('#imageStats').textContent=`Original: ${(f.size/1024).toFixed(0)} KB · ${img.width}×${img.height}`;renderImage(false)})};$('#imgW').oninput=()=>{if(imageSource&&$('#imgRatio').checked)$('#imgH').value=Math.round(+$('#imgW').value*imageSource.height/imageSource.width)};$('#imgH').oninput=()=>{if(imageSource&&$('#imgRatio').checked)$('#imgW').value=Math.round(+$('#imgH').value*imageSource.width/imageSource.height)};
function renderImage(save=true){if(!imageSource)return;const c=$('#imageCanvas'),ctx=c.getContext('2d'),w=+$('#imgW').value,h=+$('#imgH').value,rot=+$('#imgRotate').value,swap=rot%180!==0;c.width=swap?h:w;c.height=swap?w:h;ctx.translate(c.width/2,c.height/2);ctx.rotate(rot*Math.PI/180);ctx.scale($('#flipH').checked?-1:1,$('#flipV').checked?-1:1);ctx.drawImage(imageSource,+$('#cropX').value,+$('#cropY').value,+$('#cropW').value,+$('#cropH').value,-w/2,-h/2,w,h);if(save)c.toBlob(b=>{if(!b)return;$('#imageResult').textContent=`Original ${(imageOriginalSize/1024).toFixed(0)} KB → Result ${(b.size/1024).toFixed(0)} KB`;download(b,`converted.${$('#imgFormat').value.split('/')[1].replace('jpeg','jpg')}`)},$('#imgFormat').value,+$('#imgQuality').value/100)}$('#imageProcess').onclick=()=>renderImage(true);

// QR code.
let qrReady=false,lastQr='';async function ensureQr(){if(qrReady)return;try{await loadScript('https://cdn.jsdelivr.net/npm/qrcode@1.5.3/build/qrcode.min.js','QRCode');qrReady=true}catch(e){$('#qrMessage').textContent=e.message}}function qrPayload(){const t=$('#qrType').value,v=$('#qrValue').value,x=$('#qrExtra').value;if(t==='wa')return`https://wa.me/${v.replace(/\D/g,'')}?text=${encodeURIComponent(x)}`;if(t==='phone')return`tel:${v}`;if(t==='email')return`mailto:${v}?subject=${encodeURIComponent(x)}`;if(t==='sms')return`sms:${v}?body=${encodeURIComponent(x)}`;if(t==='wifi')return`WIFI:T:WPA;S:${v};P:${x};;`;return v}$('#qrMake').onclick=async()=>{await ensureQr();lastQr=qrPayload();if(!lastQr)return;const opts={width:+$('#qrSize').value,margin:+$('#qrMargin').value,errorCorrectionLevel:$('#qrLevel').value,color:{dark:$('#qrFg').value,light:$('#qrBg').value}};await QRCode.toCanvas($('#qrCanvas'),lastQr,opts);$('#qrPng').disabled=$('#qrSvg').disabled=false};$('#qrPng').onclick=()=>$('#qrCanvas').toBlob(b=>download(b,'qr-code.png'));$('#qrSvg').onclick=async()=>download(new Blob([await QRCode.toString(lastQr,{type:'svg',margin:+$('#qrMargin').value,errorCorrectionLevel:$('#qrLevel').value,color:{dark:$('#qrFg').value,light:$('#qrBg').value}})],{type:'image/svg+xml'}),'qr-code.svg');

// Social media canvas.
let socialImage=null;$('#socialFile').onchange=()=>readImage($('#socialFile').files[0],img=>{socialImage=img;renderSocial()});['socialPreset','socialMode','socialZoom','socialBg','socialX','socialY'].forEach(id=>$('#'+id).oninput=renderSocial);function renderSocial(){const [w,h]=$('#socialPreset').value.split('x').map(Number),c=$('#socialCanvas'),ctx=c.getContext('2d');c.width=w;c.height=h;ctx.fillStyle=$('#socialBg').value;ctx.fillRect(0,0,w,h);if(!socialImage)return;const base=$('#socialMode').value==='fill'?Math.max(w/socialImage.width,h/socialImage.height):Math.min(w/socialImage.width,h/socialImage.height),s=base*+$('#socialZoom').value/100,dw=socialImage.width*s,dh=socialImage.height*s,x=(w-dw)/2+(+$('#socialX').value/100)*w/2,y=(h-dh)/2+(+$('#socialY').value/100)*h/2;ctx.drawImage(socialImage,x,y,dw,dh)}$('#socialDownload').onclick=()=>{if(!socialImage)return;renderSocial();$('#socialCanvas').toBlob(b=>download(b,`social-${$('#socialPreset').value}.jpg`),'image/jpeg',.92)};

// Palette extraction using deterministic RGB quantization.
let paletteImage=null,paletteColors=[];$('#paletteFile').onchange=()=>readImage($('#paletteFile').files[0],img=>paletteImage=img);function hex(rgb){return'#'+rgb.map(v=>v.toString(16).padStart(2,'0')).join('').toUpperCase()}function hsl([r,g,b]){r/=255;g/=255;b/=255;const M=Math.max(r,g,b),m=Math.min(r,g,b),d=M-m;let h=0;if(d)h=M===r?((g-b)/d)%6:M===g?(b-r)/d+2:(r-g)/d+4;h=Math.round(h*60);if(h<0)h+=360;const l=(M+m)/2,s=d?d/(1-Math.abs(2*l-1)):0;return`${h}°, ${Math.round(s*100)}%, ${Math.round(l*100)}%`}$('#paletteExtract').onclick=()=>{if(!paletteImage)return;const c=document.createElement('canvas'),ctx=c.getContext('2d'),w=120,h=Math.max(1,Math.round(120*paletteImage.height/paletteImage.width));c.width=w;c.height=h;ctx.drawImage(paletteImage,0,0,w,h);const data=ctx.getImageData(0,0,w,h).data,bins=new Map;for(let i=0;i<data.length;i+=16){if(data[i+3]<180)continue;const rgb=[data[i],data[i+1],data[i+2]].map(v=>Math.round(v/32)*32>255?255:Math.round(v/32)*32),k=rgb.join(',');bins.set(k,(bins.get(k)||0)+1)}paletteColors=[...bins].sort((a,b)=>b[1]-a[1]).slice(0,+$('#paletteCount').value).map(x=>x[0].split(',').map(Number));renderPalette();$('#paletteExport').disabled=false};function renderPalette(){const p=$('#palettePreview');p.textContent='';paletteColors.forEach(rgb=>{const d=document.createElement('div');d.className='swatch';d.style.background=hex(rgb);d.innerHTML=`<button>Copy ${hex(rgb)}</button><span>RGB ${rgb.join(', ')}<br>HSL ${hsl(rgb)}</span>`;d.querySelector('button').onclick=()=>navigator.clipboard.writeText(hex(rgb));p.append(d)})}$('#paletteExport').onclick=()=>{const c=document.createElement('canvas'),ctx=c.getContext('2d');c.width=1200;c.height=500;paletteColors.forEach((rgb,i)=>{const w=c.width/paletteColors.length;ctx.fillStyle=hex(rgb);ctx.fillRect(i*w,0,w,c.height);ctx.fillStyle='#fff';ctx.font='28px sans-serif';ctx.fillText(hex(rgb),i*w+20,460)});c.toBlob(b=>download(b,'color-palette.png'))};if('EyeDropper'in window){$('#eyeDropper').hidden=false;$('#eyeDropper').onclick=async()=>{const r=await new EyeDropper().open();paletteColors.unshift(r.sRGBHex.match(/\w\w/g).map(x=>parseInt(x,16)));renderPalette()}}

// Units and scale.
const unitSets={length:{mm:.001,cm:.01,m:1,km:1000,inch:.0254,feet:.3048,yard:.9144},area:{'mm²':1e-6,'cm²':1e-4,'m²':1,'ft²':.09290304},volume:{'cm³':1e-6,'m³':1,'ft³':.028316846592}};function fillUnits(){const set=unitSets[$('#unitCategory').value];['unitFrom','unitTo'].forEach((id,j)=>{$('#'+id).innerHTML=Object.keys(set).map((u,i)=>`<option ${i===(j?1:0)?'selected':''}>${u}</option>`).join('')});calcUnits()}function calcUnits(){const set=unitSets[$('#unitCategory').value],v=+$('#unitValue').value||0,r=v*set[$('#unitFrom').value]/set[$('#unitTo').value];$('#unitResult').textContent=`${v} ${$('#unitFrom').value} = ${Number(r.toPrecision(10))} ${$('#unitTo').value}`}$('#unitCategory').onchange=fillUnits;['unitValue','unitFrom','unitTo'].forEach(id=>$('#'+id).oninput=calcUnits);const meter={mm:.001,cm:.01,m:1,inch:.0254,feet:.3048};function calcScale(){const val=+$('#scaleValue').value||0,ratio=+$('#scaleRatio').value||1,base=val*meter[$('#scaleUnit').value],real=$('#scaleMode').value==='real',meters=real?base/ratio:base*ratio,outUnit=real?'cm':'m',result=real?meters/.01:meters;$('#scaleResult').textContent=`${val} ${$('#scaleUnit').value} → ${Number(result.toPrecision(10))} ${outUnit} ${real?'on drawing':'real length'}`}['scaleMode','scaleValue','scaleUnit','scaleRatio'].forEach(id=>$('#'+id).oninput=calcScale);fillUnits();calcScale();
